UNITS = [{"id": "PEDS-U024", "ch": 3, "n": 24, "title": "NEC: Introduction & Etiopathogenesis", "sec": "Etiopathogenesis · p11", "guide": "NEC: m/c and devastating surgical emergency in neonates. Causes: prematurity (<32 wks, GI immaturity), top feeds without breastmilk (formula, cow milk -> pathogenic bacterial colonisation), other factors (asphyxia, maternal cocaine use) -> vasoconstriction of splanchnic circulation -> necrosis; inflammatory necrosis d/t infection. (Book p11)", "qs": ["PEDS-C3-001", "PEDS-C3-002", "PEDS-C3-003", "PEDS-C3-004", "PEDS-C3-005", "PEDS-C3-006", "PEDS-C3-007", "PEDS-C3-008"]}, {"id": "PEDS-U025", "ch": 3, "n": 25, "title": "NEC: Modified Bell's Staging", "sec": "Modified Bell's Staging · p11", "guide": "Stage I (Suspect NEC): bacterial colonisation + inflammation -> non-specific features (vomiting, abdominal distension); IA occult blood in stools, IB gross blood in stools; imaging normal. Stage II (Definite NEC): breaks in intestinal epithelium -> air in intestinal walls (pneumatosis intestinalis); IIa absent bowel sounds. Stage III (Complicated NEC): air + bacteria enter peritoneal cavity -> pneumoperitoneum + peritonitis; IIIa induration/redness/tenderness of abdominal wall; IIIb intestinal perforation. Air in wall -> venous drainage -> SMV -> portal vein: pneumatosis portalis. (Book p11-12)", "qs": ["PEDS-C3-009", "PEDS-C3-010", "PEDS-C3-011", "PEDS-C3-012", "PEDS-C3-013", "PEDS-C3-014", "PEDS-C3-015", "PEDS-C3-016", "PEDS-C3-017", "PEDS-C3-018", "PEDS-C3-019", "PEDS-C3-020", "PEDS-C3-021", "PEDS-C3-022", "PEDS-C3-023", "PEDS-C3-024", "PEDS-C3-025", "PEDS-C3-026"]}, {"id": "PEDS-U026", "ch": 3, "n": 26, "title": "NEC: Management", "sec": "Management (NEC) · p12", "guide": "Triad of lab findings (thrombocytopenia, metabolic acidosis, hyponatremia): seen only after stage IIb; do not have great relevance in diagnosis. Until stage IIIa: medical management - NPO, TPN, IV antibiotics (penicillin gram+ve, aminoglycoside gram-ve, metronidazole anaerobes). Antibiotic duration: stage Ia 3 days, Ib 7-10 days, II and IIIa 14 days. Stage IIIb: unstable -> 1st peritoneal drainage (emergency), after stabilization -> laparotomy -> resection + anastomosis; stable -> laparotomy directly. Untreated: m/c cause of neonatal mortality. (Book p12)", "qs": ["PEDS-C3-027", "PEDS-C3-028", "PEDS-C3-029", "PEDS-C3-030", "PEDS-C3-031", "PEDS-C3-032", "PEDS-C3-033", "PEDS-C3-034", "PEDS-C3-035", "PEDS-C3-036", "PEDS-C3-037", "PEDS-C3-038", "PEDS-C3-039", "PEDS-C3-040", "PEDS-C3-041", "PEDS-C3-042"]}, {"id": "PEDS-U027", "ch": 3, "n": 27, "title": "Sepsis: Spectrum & Classification", "sec": "Spectrum of Neonatal Sepsis · p13", "guide": "Types: generalised (septicemia); localised (specific organ systems: respiratory - pneumonia, CNS - meningitis, bones & joints - osteomyelitis, arthritis). Early onset: first 72 hrs of life, source maternal, risk factors chorioamnionitis/foul smelling liquor/ROM >72 hrs, type: pneumonia >> sepsis. Late onset: >72 hrs, hospital acquired infection, risk factors unclean hands of health professionals & caregivers, LBW (down immunity), lack of breastfeeding; equal incidence of sepsis, pneumonia and meningitis. (Book p13)", "qs": ["PEDS-C3-043", "PEDS-C3-044", "PEDS-C3-045", "PEDS-C3-046", "PEDS-C3-047", "PEDS-C3-048", "PEDS-C3-049", "PEDS-C3-050", "PEDS-C3-051", "PEDS-C3-052", "PEDS-C3-053", "PEDS-C3-054", "PEDS-C3-055", "PEDS-C3-056", "PEDS-C3-057", "PEDS-C3-058", "PEDS-C3-059"]}, {"id": "PEDS-U028", "ch": 3, "n": 28, "title": "Sepsis: Etiology & Clinical Features", "sec": "Etiology & Clinical Features · p13", "guide": "India: 1. Klebsiella (m/c), 2. Acinetobacter, 3. S. aureus. Worldwide: 1. Group B Streptococcus (GBS), 2. E. coli, 3. Listeria. Weak immune response -> non-specific symptoms -> suspect sepsis in any sick baby. Early symptoms: change in feeding pattern, lethargy, hypothermia >> fever. Pneumonia: respiratory distress. Meningitis: fever and irritability (non specific), seizures. (Book p13)", "qs": ["PEDS-C3-060", "PEDS-C3-061", "PEDS-C3-062", "PEDS-C3-063", "PEDS-C3-064", "PEDS-C3-065", "PEDS-C3-066", "PEDS-C3-067", "PEDS-C3-068", "PEDS-C3-069", "PEDS-C3-070", "PEDS-C3-071"]}, {"id": "PEDS-U029", "ch": 3, "n": 29, "title": "Sepsis: Investigations", "sec": "Investigations · p14", "guide": "Blood culture: gold standard; disadvantage time-consuming. Sepsis screen: presence of >2 findings: TLC down (<5000/mm3), ANC down (<1800/mm3), I/T neutrophil ratio up (>0.2), micro-ESR up (>15 mm/hr), CRP up (>1 mg/dl). Newest marker: up procalcitonin. LP: indication = suspicion of meningitis in all symptomatic babies; C/I = asymptomatic babies (even with risk factors). (Book p14)", "qs": ["PEDS-C3-072", "PEDS-C3-073", "PEDS-C3-074", "PEDS-C3-075", "PEDS-C3-076", "PEDS-C3-077", "PEDS-C3-078", "PEDS-C3-079", "PEDS-C3-080", "PEDS-C3-081", "PEDS-C3-082"]}, {"id": "PEDS-U030", "ch": 3, "n": 30, "title": "Sepsis: Treatment", "sec": "Treatment · p14", "guide": "Empirical antibiotics (while awaiting culture): low resistance: penicillin (gram+ve cover) + aminoglycoside (amikacin/gentamicin); suspected meningitis: ampicillin + 3rd gen cephalosporin (cefotaxime); high resistance: ciprofloxacin (+amikacin) or piperacillin-tazobactam + amikacin (m/c). Duration: culture negative 5-7 days (1 week); culture positive: meningitis 3 weeks, others 2 weeks. (Book p14)", "qs": ["PEDS-C3-083", "PEDS-C3-084", "PEDS-C3-085", "PEDS-C3-086", "PEDS-C3-087", "PEDS-C3-088", "PEDS-C3-089", "PEDS-C3-090"]}, {"id": "PEDS-U031", "ch": 3, "n": 31, "title": "Sepsis Algorithm", "sec": "Sepsis Algorithm · p15", "guide": "Suspected sepsis: early onset (<72 hrs) with risk factors -> start antibiotics + blood culture; then symptoms (LP indications): present -> perform LP, absent -> no LP; no risk factors -> close monitoring. Late onset (>72 hrs): no symptoms -> close monitoring; symptoms: sick baby -> antibiotics, blood culture, LP; not sick -> sepsis screen (+ -> same triad). (Book p15)", "qs": ["PEDS-C3-091", "PEDS-C3-092", "PEDS-C3-093", "PEDS-C3-094", "PEDS-C3-095", "PEDS-C3-096", "PEDS-C3-097", "PEDS-C3-098"]}]

def q(num, sec, page, qtext, opts, ans, exp):
    assert len(opts)==4 and 0 <= ans <4
    return {"id": f"PEDS-C3-{num:03d}", "sec": sec, "page": page, "q": qtext, "opts": opts, "ans": ans, "exp": exp}

